BEGIN IMMEDIATE;

CREATE TABLE _schema_migration (name TEXT PRIMARY KEY, sha256 TEXT NOT NULL, applied_at_ms INTEGER NOT NULL);

CREATE TABLE backtest_deletion (
  backtest_id TEXT PRIMARY KEY REFERENCES backtest_run(backtest_id),
  deleted_at_ms INTEGER NOT NULL CHECK(deleted_at_ms>0),
  strategy_deletion_id TEXT REFERENCES strategy_deletion(deletion_id)
) STRICT;

CREATE TABLE backtest_run (
  backtest_id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES job(job_id),
  strategy_id TEXT NOT NULL,
  strategy_version INTEGER NOT NULL,
  requested_start TEXT NOT NULL CHECK(date(requested_start,'+0 days') IS requested_start),
  requested_end TEXT NOT NULL CHECK(date(requested_end,'+0 days') IS requested_end),
  input_snapshots_json TEXT NOT NULL CHECK(json_valid(input_snapshots_json)),
  required_features_json TEXT NOT NULL CHECK(json_valid(required_features_json)),
  warmup_contract_json TEXT NOT NULL CHECK(json_valid(warmup_contract_json)),
  range_acceptance_json TEXT NOT NULL CHECK(json_valid(range_acceptance_json)), -- 连续覆盖交集/缺口/题材可得时点
  strategy_snapshot_json TEXT NOT NULL CHECK(json_valid(strategy_snapshot_json)),
  execution_config_json TEXT NOT NULL CHECK(json_valid(execution_config_json)),
  engine_version TEXT NOT NULL,
  input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
  status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled')),
  result_snapshot_id TEXT REFERENCES dataset_snapshot(snapshot_id),
  summary_json TEXT CHECK(summary_json IS NULL OR json_valid(summary_json)),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  completed_at_ms INTEGER,
  FOREIGN KEY(strategy_id,strategy_version) REFERENCES strategy_version(strategy_id,version),
  CHECK(requested_start<=requested_end),
  CHECK(status<>'completed' OR (result_snapshot_id IS NOT NULL AND summary_json IS NOT NULL AND completed_at_ms IS NOT NULL))
) STRICT;

CREATE TABLE business_clock (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  business_date TEXT NOT NULL CHECK(date(business_date,'+0 days') IS business_date),
  calendar_snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  changed_at_ms INTEGER NOT NULL CHECK(changed_at_ms>0)
) STRICT;

CREATE TABLE capability_probe (
  probe_id TEXT PRIMARY KEY,
  connection_id TEXT NOT NULL REFERENCES provider_connection(connection_id),
  capability TEXT NOT NULL, -- daily_k/index/topic/current_members等，逐能力验收
  document_support TEXT NOT NULL CHECK(document_support IN ('supported','client_only','unsupported','unknown')),
  account_access TEXT NOT NULL CHECK(account_access IN ('allowed','denied','untested','temporary_error')),
  coverage_state TEXT NOT NULL CHECK(coverage_state IN ('ready','partial','unknown','unavailable')),
  probed_at_ms INTEGER NOT NULL CHECK(probed_at_ms>0),
  schema_version TEXT NOT NULL,
  evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), -- 已脱敏证据、单位、实际范围，不是原始鉴权响应
  request_id TEXT
) STRICT;

CREATE TABLE chart_annotation (
    annotation_id TEXT PRIMARY KEY,
    instrument_id TEXT NOT NULL,
    price REAL NOT NULL CHECK(price > 0),
    label TEXT NOT NULL DEFAULT '',
    color TEXT NOT NULL CHECK(color IN ('blue','amber','red','green','violet')),
    price_basis TEXT NOT NULL CHECK(price_basis IN ('none','forward_event_affine')),
    anchor_date TEXT,
    created_at_ms INTEGER NOT NULL,
    updated_at_ms INTEGER NOT NULL, line_type TEXT NOT NULL DEFAULT 'reference' CHECK(line_type IN ('reference','support','resistance')), alert_modes_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(alert_modes_json) AND json_type(alert_modes_json)='array'), auto_watchlist INTEGER NOT NULL DEFAULT 0 CHECK(auto_watchlist IN (0,1)), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), effective_business_date TEXT CHECK(effective_business_date IS NULL OR date(effective_business_date,'+0 days') IS effective_business_date),
    CHECK((price_basis='none' AND anchor_date IS NULL) OR
          (price_basis='forward_event_affine' AND anchor_date IS NOT NULL))
);

CREATE TABLE dataset_snapshot (
  snapshot_id TEXT PRIMARY KEY,
  module TEXT NOT NULL CHECK(module IN ('calendar','security_identity','daily_raw','corporate_actions','analysis_bars','indicators','topics','market_review','backtest_result')),
  scope_key TEXT NOT NULL, -- 规范化统计范围的hash；沪深与沪深京不得共用
  job_id TEXT NOT NULL REFERENCES job(job_id),
  parent_snapshot_id TEXT REFERENCES dataset_snapshot(snapshot_id),
  data_begin TEXT NOT NULL CHECK(date(data_begin,'+0 days') IS data_begin),
  data_end TEXT NOT NULL CHECK(date(data_end,'+0 days') IS data_end),
  knowledge_cutoff_ms INTEGER NOT NULL CHECK(knowledge_cutoff_ms>0), -- 当时已知数据截止时点
  price_basis TEXT NOT NULL CHECK(price_basis IN ('none','forward','backward','not_applicable')),
  adjustment_anchor TEXT CHECK(adjustment_anchor IS NULL OR date(adjustment_anchor,'+0 days') IS adjustment_anchor),
  algorithm_version TEXT NOT NULL,
  lineage_json TEXT NOT NULL CHECK(json_valid(lineage_json)), -- 原始对象hash、源、依赖快照及单位契约
  manifest_path TEXT NOT NULL CHECK(substr(manifest_path,1,1)<>'/' AND instr(manifest_path,'..')=0 AND instr(manifest_path,'://')=0),
  manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
  state TEXT NOT NULL CHECK(state IN ('staged','validated','published','rejected')),
  quality TEXT NOT NULL CHECK(quality IN ('ready','partial','unknown','invalid')),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  published_at_ms INTEGER,
  CHECK(data_begin<=data_end),
  CHECK(price_basis NOT IN ('forward','backward') OR adjustment_anchor IS NOT NULL),
  CHECK(state<>'published' OR (published_at_ms IS NOT NULL AND quality<>'invalid'))
) STRICT;

CREATE TABLE job (
  job_id TEXT PRIMARY KEY,
  request_key TEXT NOT NULL UNIQUE, -- 前端一次手动请求的幂等键；再次主动运行用新键
  logical_key TEXT NOT NULL, -- 日期/能力/配置hash，同参数可有多次历史任务
  kind TEXT NOT NULL CHECK(kind IN ('initialise','increment','source_check','topic_init','topic_refresh','selection','tracking_review','backtest','research','cleanup','restore')),
  target_date TEXT CHECK(target_date IS NULL OR date(target_date,'+0 days') IS target_date),
  requested_by TEXT NOT NULL DEFAULT 'manual',
  parameters_json TEXT NOT NULL CHECK(json_valid(parameters_json)),
  parameters_hash TEXT NOT NULL CHECK(length(parameters_hash)=64),
  status TEXT NOT NULL CHECK(status IN ('queued','running','paused','succeeded','no_change','partial','failed','cancelled')),
  phase TEXT NOT NULL DEFAULT 'queued',
  accepted_batches INTEGER NOT NULL DEFAULT 0 CHECK(accepted_batches>=0),
  planned_batches INTEGER CHECK(planned_batches IS NULL OR planned_batches>=accepted_batches),
  retry_of_job_id TEXT REFERENCES job(job_id),
  lease_owner TEXT, -- 唯一consumer实例身份，非API账号
  lease_expires_at_ms INTEGER, -- 已授权running任务崩溃后才可凭过期租约恢复
  recovery_count INTEGER NOT NULL DEFAULT 0 CHECK(recovery_count>=0),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  finished_at_ms INTEGER,
  error_summary TEXT,
  CHECK(finished_at_ms IS NULL OR finished_at_ms>=created_at_ms)
) STRICT;

CREATE TABLE job_event (
 job_id TEXT NOT NULL REFERENCES job(job_id),
 seq INTEGER NOT NULL CHECK(seq>0),
 occurred_at_ms INTEGER NOT NULL CHECK(occurred_at_ms>0),
 level TEXT NOT NULL CHECK(level IN ('info','warning','error')),
 stage TEXT NOT NULL,
 message TEXT NOT NULL,
 details_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details_json)), -- 已脱敏结构；禁止Key/签名URL
 PRIMARY KEY(job_id,seq)
) STRICT;

CREATE TABLE line_alert_check (
 job_id TEXT PRIMARY KEY REFERENCES job(job_id),
 business_date TEXT NOT NULL,
 market_snapshot_id TEXT NOT NULL,
 rules_signature TEXT NOT NULL,
 checked_rules INTEGER NOT NULL,
 trigger_count INTEGER NOT NULL,
 unknown_count INTEGER NOT NULL,
 checked_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE line_alert_evaluation (
 job_id TEXT NOT NULL REFERENCES job(job_id),
 annotation_id TEXT NOT NULL,
 annotation_revision INTEGER NOT NULL,
 rule TEXT NOT NULL,
 trade_date TEXT NOT NULL CHECK(date(trade_date,'+0 days') IS trade_date),
 state TEXT NOT NULL CHECK(state IN ('triggered','invalidated','not_triggered','unknown')),
 reason TEXT,
 event_id TEXT REFERENCES line_alert_event(event_id),
 recorded_at_ms INTEGER NOT NULL,
 PRIMARY KEY(job_id,annotation_id,annotation_revision,rule,trade_date)
) STRICT;

CREATE TABLE line_alert_event (
 event_id TEXT PRIMARY KEY,
 annotation_id TEXT NOT NULL,
 annotation_revision INTEGER NOT NULL,
 instrument_id TEXT NOT NULL,
 line_type TEXT NOT NULL CHECK(line_type IN ('support','resistance')),
 rule TEXT NOT NULL,
 trade_date TEXT NOT NULL CHECK(date(trade_date,'+0 days') IS trade_date),
 state TEXT NOT NULL CHECK(state IN ('triggered','invalidated')),
 job_id TEXT NOT NULL REFERENCES job(job_id),
 event_json TEXT NOT NULL CHECK(json_valid(event_json)),
 created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
 UNIQUE(annotation_id,annotation_revision,rule,trade_date)
) STRICT;

CREATE TABLE line_alert_rule_clock (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 revision INTEGER NOT NULL CHECK(revision>0)
) STRICT;

CREATE TABLE listing_status_confirmation (
 confirmation_id TEXT PRIMARY KEY,
 instrument_id TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('pending','unknown')),
 source_kind TEXT NOT NULL CHECK(source_kind='manual_user_confirmation'),
 observed_business_date TEXT NOT NULL CHECK(date(observed_business_date,'+0 days') IS observed_business_date),
 reason TEXT NOT NULL,
 evidence TEXT NOT NULL,
 primary_snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
 market_snapshot_id TEXT NOT NULL,
 quote_presence_json TEXT NOT NULL CHECK(json_valid(quote_presence_json)),
 request_key TEXT NOT NULL,
 request_hash TEXT NOT NULL,
 created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
 UNIQUE(request_key,instrument_id)
) STRICT;

CREATE TABLE listing_status_revision (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 revision INTEGER NOT NULL CHECK(revision>0)
) STRICT;

CREATE TABLE listing_status_summary (
 summary_id TEXT PRIMARY KEY,
 market_snapshot_id TEXT NOT NULL,
 primary_snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
 business_date TEXT NOT NULL CHECK(date(business_date,'+0 days') IS business_date),
 manual_revision INTEGER NOT NULL CHECK(manual_revision>=0),
 reference_hash TEXT NOT NULL,
 identities_json TEXT NOT NULL CHECK(json_valid(identities_json)),
 presence_json TEXT NOT NULL CHECK(json_valid(presence_json)),
 checked_at_ms INTEGER NOT NULL,
 UNIQUE(primary_snapshot_id,market_snapshot_id,business_date,manual_revision,reference_hash)
) STRICT;

CREATE TABLE market_mainline_revision (
 revision_id TEXT PRIMARY KEY,
 trade_date TEXT NOT NULL CHECK(date(trade_date,'+0 days') IS trade_date),
 instrument_id TEXT NOT NULL,
 instrument_name TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>0),
 action TEXT NOT NULL CHECK(action IN ('replace','revoke')),
 source_kind TEXT NOT NULL CHECK(source_kind='manual_user_entry'),
 change_reason TEXT NOT NULL CHECK(length(trim(change_reason))>0),
 attributions_json TEXT NOT NULL CHECK(json_valid(attributions_json) AND json_type(attributions_json)='array'),
 recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0),
 supersedes_revision_id TEXT REFERENCES market_mainline_revision(revision_id),
 UNIQUE(trade_date,instrument_id,revision),
 CHECK((action='revoke' AND json_array_length(attributions_json)=0)
    OR (action='replace' AND json_array_length(attributions_json) BETWEEN 1 AND 12))
) STRICT;

CREATE TABLE market_sentiment_snapshot (
 snapshot_id TEXT PRIMARY KEY,
 trade_date TEXT NOT NULL CHECK(date(trade_date,'+0 days') IS trade_date),
 recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0),
 record_mode TEXT NOT NULL CHECK(record_mode='manual_retained_capture'),
 model TEXT NOT NULL CHECK(length(model) BETWEEN 1 AND 128),
 rule_version TEXT NOT NULL CHECK(length(rule_version) BETWEEN 1 AND 128),
 input_fingerprint TEXT NOT NULL CHECK(length(input_fingerprint)=64 AND input_fingerprint NOT GLOB '*[^0-9a-f]*'),
 content_sha256 TEXT NOT NULL CHECK(length(content_sha256)=64 AND content_sha256 NOT GLOB '*[^0-9a-f]*'),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND json_type(payload_json)='object' AND length(payload_json)<=1048576),
 UNIQUE(trade_date,rule_version,input_fingerprint),
 CHECK(json_extract(payload_json,'$.date') IS trade_date),
 CHECK(json_extract(payload_json,'$.model') IS model),
 CHECK(json_extract(payload_json,'$.provenance.rule_version') IS rule_version),
 CHECK(json_extract(payload_json,'$.provenance.input_fingerprint') IS input_fingerprint),
 CHECK(json_extract(payload_json,'$.provenance.mode') IS 'retained_retrospective')
) STRICT;

CREATE TABLE platform_setting (
  key TEXT PRIMARY KEY,
  value_json TEXT NOT NULL CHECK(json_valid(value_json)),
  updated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE provider_connection (
  connection_id TEXT PRIMARY KEY, -- 账号连接的内部ID，不是Key
  provider_code TEXT NOT NULL, -- fuyao/tickflow等适配器ID
  label TEXT NOT NULL,
  access_mode TEXT NOT NULL CHECK(access_mode IN ('public','key')),
  credential_ref TEXT, -- 仅操作系统钥匙串/后端secret的不透明引用，禁止密钥正文
  enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  CHECK(access_mode='public' OR credential_ref IS NOT NULL)
) STRICT;

CREATE TABLE published_head (
  module TEXT NOT NULL,
  scope_key TEXT NOT NULL,
  snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  changed_at_ms INTEGER NOT NULL CHECK(changed_at_ms>0),
  PRIMARY KEY(module,scope_key)
) STRICT;

CREATE TABLE research_report (
  report_id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES job(job_id),
  instrument_id TEXT NOT NULL,
  data_cutoff TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  report_json TEXT NOT NULL CHECK(json_valid(report_json)),
  snapshot_refs_json TEXT NOT NULL CHECK(json_valid(snapshot_refs_json))
, last_accessed_at_ms INTEGER NOT NULL DEFAULT 0 CHECK(last_accessed_at_ms>=0), expires_at_ms INTEGER NOT NULL DEFAULT 0 CHECK(expires_at_ms>=0)) STRICT;

CREATE TABLE retention_pin (
  pin_id TEXT PRIMARY KEY,
  snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  owner_kind TEXT NOT NULL CHECK(owner_kind IN ('request','selection','tracking','backtest','research','backup','manual')),
  owner_id TEXT NOT NULL, -- 多态owner由worker核验；不伪造跨表外键
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  expires_at_ms INTEGER, -- 请求租约可到期；运行和跟踪依据默认NULL长期保留
  UNIQUE(snapshot_id,owner_kind,owner_id),
  CHECK(expires_at_ms IS NULL OR expires_at_ms>created_at_ms)
) STRICT;

CREATE TABLE sector_selection_candidate (
 run_id TEXT NOT NULL REFERENCES sector_selection_run(run_id),
 topic_code TEXT NOT NULL,
 sector_kind TEXT NOT NULL CHECK(sector_kind IN ('industry','concept')),
 name TEXT NOT NULL,
 decision TEXT NOT NULL CHECK(decision IN ('matched','unmatched','unknown')),
 close_price_e8 INTEGER,
 metrics_json TEXT NOT NULL CHECK(json_valid(metrics_json)),
 checks_json TEXT NOT NULL CHECK(json_valid(checks_json)),
 cache_refs_json TEXT NOT NULL CHECK(json_valid(cache_refs_json)),
 PRIMARY KEY(run_id,topic_code)
);

CREATE TABLE sector_selection_run (
 run_id TEXT PRIMARY KEY,
 job_id TEXT NOT NULL UNIQUE REFERENCES job(job_id),
 strategy_id TEXT NOT NULL,
 strategy_version INTEGER NOT NULL,
 business_date TEXT NOT NULL,
 market_snapshot_id TEXT NOT NULL,
 catalog_signature TEXT NOT NULL,
 input_sha256 TEXT NOT NULL,
 cache_refs_json TEXT NOT NULL CHECK(json_valid(cache_refs_json)),
 status TEXT NOT NULL CHECK(status IN ('running','completed')),
 created_at_ms INTEGER NOT NULL,
 completed_at_ms INTEGER,
 FOREIGN KEY(strategy_id,strategy_version) REFERENCES sector_strategy_version(strategy_id,version)
);

CREATE TABLE sector_strategy (
 strategy_id TEXT PRIMARY KEY,
 name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100),
 current_version INTEGER NOT NULL DEFAULT 1 CHECK(current_version>0),
 archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),
 created_at_ms INTEGER NOT NULL
);

CREATE TABLE sector_strategy_version (
 strategy_id TEXT NOT NULL REFERENCES sector_strategy(strategy_id),
 version INTEGER NOT NULL CHECK(version>0),
 period TEXT NOT NULL CHECK(period IN ('D','W','M')),
 sector_kind TEXT NOT NULL CHECK(sector_kind IN ('all','industry','concept')),
 definition_json TEXT NOT NULL CHECK(json_valid(definition_json)),
 definition_sha256 TEXT NOT NULL,
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),
 evaluator_version TEXT NOT NULL,
 recorded_at_ms INTEGER NOT NULL,
 PRIMARY KEY(strategy_id,version)
);

CREATE TABLE sector_tracking_event (
 event_id TEXT PRIMARY KEY,
 event_key TEXT NOT NULL UNIQUE,
 round_id TEXT NOT NULL REFERENCES sector_tracking_round(round_id),
 event_type TEXT NOT NULL CHECK(event_type IN ('entry','review','alert','condition_end','expire','manual_remove','policy_change')),
 business_date TEXT NOT NULL CHECK(date(business_date,'+0 days') IS business_date),
 policy_revision INTEGER NOT NULL CHECK(policy_revision>0),
 data_state TEXT NOT NULL CHECK(data_state IN ('ready','unknown','not_applicable')),
 outcome TEXT NOT NULL CHECK(outcome IN ('satisfied','not_satisfied','unknown','not_applicable')),
 trading_age INTEGER CHECK(trading_age>=0),
 evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)),
 recorded_at_ms INTEGER NOT NULL
);

CREATE TABLE sector_tracking_round (
 round_id TEXT PRIMARY KEY,
 strategy_id TEXT NOT NULL,
 entry_strategy_version INTEGER NOT NULL,
 origin_run_id TEXT NOT NULL,
 target_id TEXT NOT NULL,
 topic_code TEXT NOT NULL CHECK(topic_code=target_id),
 topic_id TEXT NOT NULL,
 name TEXT NOT NULL,
 sector_kind TEXT NOT NULL CHECK(sector_kind IN ('industry','concept')),
 entry_period TEXT NOT NULL CHECK(entry_period IN ('D','W','M')),
 entry_business_date TEXT NOT NULL CHECK(date(entry_business_date,'+0 days') IS entry_business_date),
 entry_price_e8 INTEGER NOT NULL CHECK(entry_price_e8>0),
 entry_high_e8 INTEGER CHECK(entry_high_e8>0),
 entry_low_e8 INTEGER CHECK(entry_low_e8>0),
 entry_market_snapshot_id TEXT NOT NULL,
 entry_cache_refs_json TEXT NOT NULL CHECK(json_valid(entry_cache_refs_json)),
 entry_basis_json TEXT NOT NULL CHECK(json_valid(entry_basis_json)),
 entry_policy_json TEXT NOT NULL CHECK(json_valid(entry_policy_json)),
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),
 policy_revision INTEGER NOT NULL DEFAULT 1 CHECK(policy_revision>0),
 duration_sessions INTEGER NOT NULL CHECK(duration_sessions BETWEEN 1 AND 750),
 status TEXT NOT NULL DEFAULT 'tracking' CHECK(status IN ('tracking','expired','condition_ended','manual_removed')),
 end_business_date TEXT,
 end_reason TEXT,
 created_at_ms INTEGER NOT NULL,
 updated_at_ms INTEGER NOT NULL,
 FOREIGN KEY(strategy_id,entry_strategy_version) REFERENCES sector_strategy_version(strategy_id,version),
 FOREIGN KEY(origin_run_id,topic_code) REFERENCES sector_selection_candidate(run_id,topic_code),
 CHECK(entry_high_e8 IS NULL OR entry_high_e8>=entry_price_e8),
 CHECK(entry_low_e8 IS NULL OR entry_low_e8<=entry_price_e8),
 CHECK((status='tracking' AND end_business_date IS NULL) OR
       (status<>'tracking' AND end_business_date>=entry_business_date))
);

CREATE TABLE selection_candidate (
  run_id TEXT NOT NULL REFERENCES selection_run(run_id),
  instrument_id TEXT NOT NULL, -- 内部稳定证券ID；不能只用6位代码
  decision TEXT NOT NULL CHECK(decision IN ('matched','unmatched','unknown')),
  close_price_e8 INTEGER CHECK(close_price_e8 IS NULL OR close_price_e8>0), -- CNY/股×10^8
  checks_json TEXT NOT NULL CHECK(json_valid(checks_json)),
  metrics_json TEXT NOT NULL CHECK(json_valid(metrics_json)),
  topic_snapshot_json TEXT NOT NULL CHECK(json_valid(topic_snapshot_json)),
  PRIMARY KEY(run_id,instrument_id)
) STRICT;

CREATE TABLE selection_run (
  run_id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES job(job_id),
  strategy_id TEXT NOT NULL,
  strategy_version INTEGER NOT NULL,
  business_date TEXT NOT NULL CHECK(date(business_date,'+0 days') IS business_date),
  primary_snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  input_snapshots_json TEXT NOT NULL CHECK(json_valid(input_snapshots_json)), -- calendar/raw/indicators/topics等精确ID列表
  input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
  status TEXT NOT NULL CHECK(status IN ('running','completed','failed')),
  universe_definition_json TEXT NOT NULL CHECK(json_valid(universe_definition_json)),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  completed_at_ms INTEGER,
  FOREIGN KEY(strategy_id,strategy_version) REFERENCES strategy_version(strategy_id,version)
) STRICT;

CREATE TABLE snapshot_artifact (
  snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  object_key TEXT NOT NULL CHECK(substr(object_key,1,1)<>'/' AND instr(object_key,'..')=0 AND instr(object_key,'://')=0),
  role TEXT NOT NULL, -- daily_raw/calendar/topic_pit等已知事实集
  sha256 TEXT NOT NULL CHECK(length(sha256)=64),
  byte_count INTEGER NOT NULL CHECK(byte_count>=0),
  row_count INTEGER CHECK(row_count IS NULL OR row_count>=0),
  PRIMARY KEY(snapshot_id,object_key)
) STRICT;

CREATE TABLE snapshot_coverage (
  snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  feature TEXT NOT NULL, -- 一项功能所需的字段/范围契约，不等于账号已验权
  scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),
  coverage_state TEXT NOT NULL CHECK(coverage_state IN ('ready','partial','unknown','unavailable')),
  observed_rows INTEGER NOT NULL CHECK(observed_rows>=0),
  expected_rows INTEGER CHECK(expected_rows IS NULL OR expected_rows>=0),
  unexplained_missing INTEGER NOT NULL DEFAULT 0 CHECK(unexplained_missing>=0),
  continuous_begin TEXT CHECK(continuous_begin IS NULL OR date(continuous_begin,'+0 days') IS continuous_begin),
  continuous_end TEXT CHECK(continuous_end IS NULL OR date(continuous_end,'+0 days') IS continuous_end),
  gaps_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(gaps_json)), -- 逐日缺口对象或受管理文件引用
  exceptions_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(exceptions_json)), -- 未上市/已确认停牌/未知分别保留
  PRIMARY KEY(snapshot_id,feature),
  CHECK((continuous_begin IS NULL)=(continuous_end IS NULL)),
  CHECK(continuous_begin IS NULL OR continuous_begin<=continuous_end),
  CHECK(coverage_state<>'ready' OR (unexplained_missing=0 AND continuous_begin IS NOT NULL))
) STRICT;

CREATE TABLE snapshot_gc (
  snapshot_id TEXT PRIMARY KEY REFERENCES dataset_snapshot(snapshot_id),
  state TEXT NOT NULL CHECK(state IN ('available','gc_pending','purged')),
  changed_at_ms INTEGER NOT NULL CHECK(changed_at_ms>0),
  reason TEXT NOT NULL
) STRICT;

CREATE TABLE strategy (
  strategy_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),
  current_version INTEGER,
  current_policy_version INTEGER,
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  FOREIGN KEY(strategy_id,current_version) REFERENCES strategy_version(strategy_id,version),
  FOREIGN KEY(strategy_id,current_policy_version) REFERENCES tracking_policy_version(strategy_id,policy_version)
) STRICT;

CREATE TABLE strategy_deletion (
  strategy_id TEXT PRIMARY KEY REFERENCES strategy(strategy_id),
  deletion_id TEXT NOT NULL UNIQUE,
  deleted_at_ms INTEGER NOT NULL CHECK(deleted_at_ms>0),
  previous_archived INTEGER NOT NULL CHECK(previous_archived IN (0,1))
) STRICT;

CREATE TABLE strategy_version (
  strategy_id TEXT NOT NULL REFERENCES strategy(strategy_id),
  version INTEGER NOT NULL CHECK(version>0),
  period TEXT NOT NULL CHECK(period IN ('D','W')),
  definition_json TEXT NOT NULL CHECK(json_valid(definition_json)), -- 白名单AST/题材ID/固定或动态候选范围
  definition_sha256 TEXT NOT NULL CHECK(length(definition_sha256)=64),
  evaluator_version TEXT NOT NULL,
  recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0), trade_rules_json TEXT NOT NULL DEFAULT '{"entry":null,"exit":null}' CHECK(json_valid(trade_rules_json)), signal_period TEXT
  CHECK(signal_period IS NULL OR signal_period IN ('D','W','M')),
  PRIMARY KEY(strategy_id,version)
) STRICT;

CREATE TABLE sync_batch (
  job_id TEXT NOT NULL REFERENCES job(job_id),
  capability TEXT NOT NULL,
  batch_key TEXT NOT NULL, -- 分页游标或窗口hash；不得包含签名URL或密钥
  attempt_no INTEGER NOT NULL CHECK(attempt_no>0),
  status TEXT NOT NULL CHECK(status IN ('running','accepted','failed','cancelled')),
  fetched_at_ms INTEGER NOT NULL CHECK(fetched_at_ms>0),
  row_count INTEGER CHECK(row_count IS NULL OR row_count>=0),
  content_sha256 TEXT CHECK(content_sha256 IS NULL OR length(content_sha256)=64),
  request_id TEXT,
  diagnostic_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(diagnostic_json)),
  PRIMARY KEY(job_id,capability,batch_key,attempt_no)
) STRICT;

CREATE TABLE topic (
  topic_id TEXT PRIMARY KEY,
  origin TEXT NOT NULL CHECK(origin IN ('provider','manual')),
  connection_id TEXT REFERENCES provider_connection(connection_id),
  provider_topic_key TEXT, -- .TI或供应商稳定键；不依赖易改的中文名
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  CHECK(origin='manual' OR (connection_id IS NOT NULL AND provider_topic_key IS NOT NULL)),
  UNIQUE(connection_id,provider_topic_key)
) STRICT;

CREATE TABLE topic_override (
  override_id TEXT PRIMARY KEY,
  topic_id TEXT NOT NULL REFERENCES topic(topic_id),
  instrument_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK(action IN ('include','exclude','reset_to_provider')),
  effective_business_date TEXT NOT NULL CHECK(date(effective_business_date,'+0 days') IS effective_business_date),
  recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0),
  supersedes_override_id TEXT REFERENCES topic_override(override_id),
  reason TEXT NOT NULL
) STRICT;

CREATE TABLE topic_revision (
  topic_id TEXT NOT NULL REFERENCES topic(topic_id),
  revision INTEGER NOT NULL CHECK(revision>0),
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  aliases_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(aliases_json) AND json_type(aliases_json)='array'),
  archived INTEGER NOT NULL CHECK(archived IN (0,1)),
  effective_business_date TEXT NOT NULL CHECK(date(effective_business_date,'+0 days') IS effective_business_date),
  recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0),
  PRIMARY KEY(topic_id,revision)
) STRICT;

CREATE TABLE tracking_event (
  event_id TEXT PRIMARY KEY,
  event_key TEXT NOT NULL UNIQUE, -- round/date/type/condition/policy等规范化键；更正另记事件
  round_id TEXT NOT NULL REFERENCES tracking_round(round_id),
  event_type TEXT NOT NULL CHECK(event_type IN ('entry','review','alert','condition_end','expire','manual_remove','policy_change','correction','note')),
  business_date TEXT NOT NULL CHECK(date(business_date,'+0 days') IS business_date),
  data_snapshot_id TEXT REFERENCES dataset_snapshot(snapshot_id),
  data_state TEXT NOT NULL CHECK(data_state IN ('ready','missing','suspended','unknown','not_applicable')),
  outcome TEXT NOT NULL CHECK(outcome IN ('satisfied','not_satisfied','unknown','not_applicable')),
  trading_age INTEGER NOT NULL CHECK(trading_age>=0), -- 入池日0；按市场交易日历，不按有K线日计时
  evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), -- 价格/政策/条件值/最新题材及引用，未知保留null
  recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0)
) STRICT;

CREATE TABLE tracking_ignore (
  strategy_id TEXT NOT NULL REFERENCES strategy(strategy_id),
  instrument_id TEXT NOT NULL,
  active INTEGER NOT NULL CHECK(active IN (0,1)),
  reason TEXT NOT NULL,
  changed_at_ms INTEGER NOT NULL CHECK(changed_at_ms>0),
  PRIMARY KEY(strategy_id,instrument_id)
) STRICT;

CREATE TABLE tracking_policy_application (
  application_id TEXT PRIMARY KEY,
  round_id TEXT NOT NULL REFERENCES tracking_round(round_id),
  strategy_id TEXT NOT NULL,
  previous_policy_version INTEGER NOT NULL,
  policy_version INTEGER NOT NULL,
  effective_business_date TEXT NOT NULL CHECK(date(effective_business_date,'+0 days') IS effective_business_date),
  recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0),
  reason TEXT NOT NULL,
  FOREIGN KEY(strategy_id,policy_version) REFERENCES tracking_policy_version(strategy_id,policy_version),
  FOREIGN KEY(strategy_id,previous_policy_version) REFERENCES tracking_policy_version(strategy_id,policy_version),
  UNIQUE(round_id,policy_version,effective_business_date)
) STRICT;

CREATE TABLE tracking_policy_version (
  strategy_id TEXT NOT NULL REFERENCES strategy(strategy_id),
  policy_version INTEGER NOT NULL CHECK(policy_version>0),
  duration_sessions INTEGER NOT NULL DEFAULT 30 CHECK(duration_sessions BETWEEN 1 AND 250),
  allow_entry_day_alerts INTEGER NOT NULL DEFAULT 0 CHECK(allow_entry_day_alerts IN (0,1)),
  allow_entry_day_exits INTEGER NOT NULL DEFAULT 0 CHECK(allow_entry_day_exits IN (0,1)),
  alert_logic TEXT NOT NULL DEFAULT 'OR' CHECK(alert_logic IN ('AND','OR')),
  alerts_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(alerts_json) AND json_type(alerts_json)='array'),
  exit_logic TEXT NOT NULL DEFAULT 'OR' CHECK(exit_logic IN ('AND','OR')),
  exits_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(exits_json) AND json_type(exits_json)='array'),
  recorded_at_ms INTEGER NOT NULL CHECK(recorded_at_ms>0),
  PRIMARY KEY(strategy_id,policy_version)
) STRICT;

CREATE TABLE tracking_round (
  round_id TEXT PRIMARY KEY,
  strategy_id TEXT NOT NULL,
  entry_strategy_version INTEGER NOT NULL,
  origin_run_id TEXT NOT NULL,
  instrument_id TEXT NOT NULL,
  entry_business_date TEXT NOT NULL CHECK(date(entry_business_date,'+0 days') IS entry_business_date),
  entry_price_e8 INTEGER NOT NULL CHECK(entry_price_e8>0), -- 入池运行快照图表价；固定源/复权锚，后续比较价必须归一到本轮基准
  entry_snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  entry_policy_version INTEGER NOT NULL,
  current_policy_version INTEGER NOT NULL,
  entry_basis_json TEXT NOT NULL CHECK(json_valid(entry_basis_json)), -- 来源/复权锚/题材版本/命中依据冻结
  status TEXT NOT NULL DEFAULT 'tracking' CHECK(status IN ('tracking','expired','condition_ended','manual_removed')),
  end_business_date TEXT CHECK(end_business_date IS NULL OR date(end_business_date,'+0 days') IS end_business_date),
  end_reason TEXT,
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  FOREIGN KEY(strategy_id,entry_strategy_version) REFERENCES strategy_version(strategy_id,version),
  FOREIGN KEY(origin_run_id,instrument_id) REFERENCES selection_candidate(run_id,instrument_id),
  FOREIGN KEY(strategy_id,entry_policy_version) REFERENCES tracking_policy_version(strategy_id,policy_version),
  FOREIGN KEY(strategy_id,current_policy_version) REFERENCES tracking_policy_version(strategy_id,policy_version),
  CHECK((status='tracking' AND end_business_date IS NULL) OR (status<>'tracking' AND end_business_date>=entry_business_date)),
  CHECK(status<>'expired' OR end_business_date>entry_business_date)
) STRICT;

CREATE TABLE watchlist_item (
  instrument_id TEXT PRIMARY KEY,
  source_kind TEXT NOT NULL CHECK(source_kind IN ('stock','tracking','sector','topic')),
  source_id TEXT,
  source_name TEXT NOT NULL,
  observed_date TEXT CHECK(observed_date IS NULL OR date(observed_date,'+0 days') IS observed_date),
  added_business_date TEXT NOT NULL CHECK(date(added_business_date,'+0 days') IS added_business_date),
  tracking_round_id TEXT REFERENCES tracking_round(round_id),
  tracking_entry_date TEXT CHECK(tracking_entry_date IS NULL OR date(tracking_entry_date,'+0 days') IS tracking_entry_date),
  event_price_e8 INTEGER CHECK(event_price_e8 IS NULL OR event_price_e8>0),
  event_basis_json TEXT NOT NULL CHECK(json_valid(event_basis_json)),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0), watchlist_entry_price_e8 INTEGER
  CHECK(watchlist_entry_price_e8 IS NULL OR watchlist_entry_price_e8>0), watchlist_entry_basis_json TEXT NOT NULL DEFAULT '{}'
  CHECK(json_valid(watchlist_entry_basis_json)),
  CHECK((tracking_round_id IS NULL AND tracking_entry_date IS NULL AND event_price_e8 IS NULL)
     OR (tracking_round_id IS NOT NULL AND tracking_entry_date IS NOT NULL AND event_price_e8 IS NOT NULL))
) STRICT;

CREATE TABLE workspace_purge (
  purge_id TEXT PRIMARY KEY,
  target_kind TEXT NOT NULL CHECK(target_kind IN ('strategy','backtest')),
  target_id TEXT NOT NULL,
  target_name TEXT NOT NULL,
  job_id TEXT NOT NULL UNIQUE REFERENCES job(job_id),
  scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64),
  scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),
  status TEXT NOT NULL CHECK(status IN ('queued','cleaning','completed','failed')),
  business_deleted INTEGER NOT NULL DEFAULT 0 CHECK(business_deleted IN (0,1)),
  created_at_ms INTEGER NOT NULL,
  completed_at_ms INTEGER,
  error TEXT,
  superseded_by TEXT REFERENCES workspace_purge(purge_id)
) STRICT;

CREATE TABLE workspace_purge_audit (
  purge_id TEXT NOT NULL REFERENCES workspace_purge(purge_id),
  stage TEXT NOT NULL,
  occurred_at_ms INTEGER NOT NULL,
  details_json TEXT NOT NULL CHECK(json_valid(details_json)),
  PRIMARY KEY(purge_id,stage)
) STRICT;

CREATE TABLE workspace_purge_file (
  purge_id TEXT NOT NULL REFERENCES workspace_purge(purge_id),
  snapshot_id TEXT NOT NULL REFERENCES dataset_snapshot(snapshot_id),
  object_key TEXT NOT NULL,
  sha256 TEXT NOT NULL CHECK(length(sha256)=64),
  byte_count INTEGER NOT NULL CHECK(byte_count>=0),
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','removed','absent','failed')),
  removed_bytes INTEGER NOT NULL DEFAULT 0 CHECK(removed_bytes>=0),
  error TEXT,
  PRIMARY KEY(purge_id,object_key)
) STRICT;

CREATE INDEX artifact_content_references ON snapshot_artifact(sha256);

CREATE INDEX backtest_deletion_strategy_batch ON backtest_deletion(strategy_deletion_id);

CREATE INDEX candidates_by_result ON selection_candidate(run_id,decision);

CREATE INDEX capability_latest ON capability_probe(connection_id,capability,probed_at_ms DESC);

CREATE INDEX chart_annotation_instrument ON chart_annotation(instrument_id, created_at_ms, annotation_id);

CREATE INDEX line_alert_by_day ON line_alert_event(trade_date DESC,created_at_ms DESC);

CREATE INDEX line_alert_by_stock ON line_alert_event(instrument_id,trade_date DESC,created_at_ms DESC);

CREATE INDEX line_alert_evaluation_progress ON line_alert_evaluation(annotation_id,annotation_revision,rule,trade_date);

CREATE INDEX listing_confirmation_by_stock ON listing_status_confirmation(instrument_id,created_at_ms DESC);

CREATE INDEX listing_summary_lookup ON listing_status_summary(market_snapshot_id,business_date,manual_revision);

CREATE INDEX live_pins ON retention_pin(snapshot_id,expires_at_ms);

CREATE INDEX mainline_by_date_known ON market_mainline_revision(trade_date,recorded_at_ms,instrument_id,revision);

CREATE UNIQUE INDEX one_accepted_batch ON sync_batch(job_id,capability,batch_key) WHERE status='accepted';

CREATE UNIQUE INDEX one_active_logical_job ON job(logical_key) WHERE status IN ('queued','running','paused');

CREATE UNIQUE INDEX one_active_sector_tracking ON sector_tracking_round(strategy_id,target_id) WHERE status='tracking';

CREATE UNIQUE INDEX one_active_tracking_round ON tracking_round(strategy_id,instrument_id) WHERE status='tracking';

CREATE UNIQUE INDEX one_active_workspace_purge ON workspace_purge(target_kind,target_id) WHERE status IN ('queued','cleaning');

CREATE UNIQUE INDEX only_one_running_job ON job((1)) WHERE status='running';

CREATE INDEX research_by_instrument ON research_report(instrument_id,created_at_ms DESC);

CREATE INDEX research_cache_expiry ON research_report(expires_at_ms);

CREATE INDEX sector_selection_run_strategy ON sector_selection_run(strategy_id,created_at_ms);

CREATE INDEX sector_tracking_event_list ON sector_tracking_event(business_date DESC,event_type,round_id);

CREATE INDEX sector_tracking_status ON sector_tracking_round(status,strategy_id,created_at_ms);

CREATE INDEX sentiment_snapshot_by_date ON market_sentiment_snapshot(trade_date,recorded_at_ms DESC,snapshot_id DESC);

CREATE INDEX sentiment_snapshot_by_known ON market_sentiment_snapshot(recorded_at_ms DESC,snapshot_id DESC);

CREATE INDEX snapshots_by_module_date ON dataset_snapshot(module,scope_key,data_end DESC);

CREATE INDEX topic_override_asof ON topic_override(topic_id,instrument_id,effective_business_date,recorded_at_ms);

CREATE INDEX tracking_round_by_instrument_date
ON tracking_round(instrument_id, entry_business_date DESC, created_at_ms DESC);

CREATE INDEX trigger_list ON tracking_event(event_type,business_date DESC,round_id);

CREATE INDEX watchlist_created ON watchlist_item(created_at_ms DESC,instrument_id);

CREATE INDEX workspace_purge_target ON workspace_purge(target_kind,target_id,business_deleted);

CREATE VIEW published_watermark AS SELECT h.module,h.scope_key,h.snapshot_id,
  s.data_end AS imported_through,s.quality,s.knowledge_cutoff_ms
  FROM published_head h JOIN dataset_snapshot s USING(snapshot_id);

CREATE TRIGGER advance_listing_status_revision AFTER INSERT ON listing_status_confirmation
BEGIN INSERT INTO listing_status_revision VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER append_only_capability_probe_delete BEFORE DELETE ON capability_probe BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_capability_probe_update BEFORE UPDATE ON capability_probe BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_job_event_delete BEFORE DELETE ON job_event BEGIN SELECT RAISE(ABORT,'retain task history'); END;

CREATE TRIGGER append_only_job_event_update BEFORE UPDATE ON job_event BEGIN SELECT RAISE(ABORT,'task log is append only'); END;

CREATE TRIGGER append_only_strategy_version_delete BEFORE DELETE ON strategy_version WHEN workspace_purge_allowed('strategy',OLD.strategy_id)=0 BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_strategy_version_update BEFORE UPDATE ON strategy_version BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_topic_override_delete BEFORE DELETE ON topic_override BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_topic_override_update BEFORE UPDATE ON topic_override BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_topic_revision_delete BEFORE DELETE ON topic_revision BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_topic_revision_update BEFORE UPDATE ON topic_revision BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_tracking_event_delete BEFORE DELETE ON tracking_event WHEN workspace_purge_allowed('round',OLD.round_id)=0 BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_tracking_event_update BEFORE UPDATE ON tracking_event BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_tracking_policy_application_delete BEFORE DELETE ON tracking_policy_application WHEN workspace_purge_allowed('round',OLD.round_id)=0 BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_tracking_policy_application_update BEFORE UPDATE ON tracking_policy_application BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_tracking_policy_version_delete BEFORE DELETE ON tracking_policy_version WHEN workspace_purge_allowed('strategy',OLD.strategy_id)=0 BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER append_only_tracking_policy_version_update BEFORE UPDATE ON tracking_policy_version BEGIN SELECT RAISE(ABORT,'append-only evidence; create a new version'); END;

CREATE TRIGGER backtest_dependency_gate BEFORE INSERT ON backtest_run BEGIN
 SELECT CASE WHEN json_type(NEW.input_snapshots_json)<>'object' OR EXISTS(
  SELECT 1 FROM json_each(NEW.input_snapshots_json) j WHERE j.type<>'text' OR NOT EXISTS(SELECT 1 FROM dataset_snapshot s WHERE s.snapshot_id=j.value AND s.state='published')
  OR EXISTS(SELECT 1 FROM snapshot_gc g WHERE g.snapshot_id=j.value AND g.state<>'available')) THEN RAISE(ABORT,'backtest dependencies must be available published snapshots') END;
END;

CREATE TRIGGER backtest_input_immutable BEFORE UPDATE ON backtest_run
WHEN NEW.strategy_id<>OLD.strategy_id OR NEW.strategy_version<>OLD.strategy_version OR NEW.requested_start<>OLD.requested_start OR NEW.requested_end<>OLD.requested_end
 OR NEW.input_snapshots_json<>OLD.input_snapshots_json OR NEW.strategy_snapshot_json<>OLD.strategy_snapshot_json OR NEW.execution_config_json<>OLD.execution_config_json
 OR NEW.engine_version<>OLD.engine_version OR NEW.input_sha256<>OLD.input_sha256 OR NEW.required_features_json<>OLD.required_features_json OR NEW.warmup_contract_json<>OLD.warmup_contract_json
BEGIN SELECT RAISE(ABORT,'backtest inputs are frozen; create a new run'); END;

CREATE TRIGGER backtest_insert_queued BEFORE INSERT ON backtest_run WHEN NEW.status<>'queued' BEGIN SELECT RAISE(ABORT,'backtest begins queued'); END;

CREATE TRIGGER backtest_start_range_gate BEFORE UPDATE OF status ON backtest_run WHEN NEW.status='running' BEGIN
 SELECT CASE WHEN OLD.status<>'queued' THEN RAISE(ABORT,'only queued backtest can start; rerun failed task with a new ID') END;
 SELECT CASE WHEN json_extract(NEW.range_acceptance_json,'$.accepted') IS NOT 1
 OR json_extract(NEW.range_acceptance_json,'$.accepted_start') IS NOT NEW.requested_start
 OR json_extract(NEW.range_acceptance_json,'$.accepted_end') IS NOT NEW.requested_end
 OR json_type(NEW.range_acceptance_json,'$.calendar_sessions') IS NOT 'integer'
 OR json_extract(NEW.range_acceptance_json,'$.calendar_sessions')<10
 OR json_extract(NEW.range_acceptance_json,'$.dependency_gaps') IS NOT 0
 THEN RAISE(ABORT,'backtest range must pass exact continuous-coverage acceptance') END;
END;

CREATE TRIGGER business_clock_insert_gate BEFORE INSERT ON business_clock BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot WHERE snapshot_id=NEW.calendar_snapshot_id AND module='calendar' AND state='published' AND data_end>=NEW.business_date) THEN RAISE(ABORT,'business clock requires a published calendar') END;
END;

CREATE TRIGGER business_clock_update_gate BEFORE UPDATE ON business_clock BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot WHERE snapshot_id=NEW.calendar_snapshot_id AND module='calendar' AND state='published' AND data_end>=NEW.business_date) THEN RAISE(ABORT,'business clock requires a published calendar') END;
 SELECT CASE WHEN NEW.business_date<OLD.business_date THEN RAISE(ABORT,'business clock cannot silently move backwards') END;
END;

CREATE TRIGGER candidate_sealed_insert BEFORE INSERT ON selection_candidate WHEN (SELECT status FROM selection_run WHERE run_id=NEW.run_id)<>'running' BEGIN SELECT RAISE(ABORT,'completed candidate set is immutable'); END;

CREATE TRIGGER chain_mainline_revision BEFORE INSERT ON market_mainline_revision
BEGIN
 SELECT CASE WHEN NEW.revision!=coalesce((SELECT max(revision) FROM market_mainline_revision WHERE trade_date=NEW.trade_date AND instrument_id=NEW.instrument_id),0)+1
 THEN RAISE(ABORT,'daily mainline revision must append') END;
 SELECT CASE WHEN NEW.supersedes_revision_id IS NOT (SELECT revision_id FROM market_mainline_revision WHERE trade_date=NEW.trade_date AND instrument_id=NEW.instrument_id ORDER BY revision DESC LIMIT 1)
 THEN RAISE(ABORT,'daily mainline predecessor mismatch') END;
 SELECT CASE WHEN NEW.recorded_at_ms<coalesce((SELECT recorded_at_ms FROM market_mainline_revision WHERE trade_date=NEW.trade_date AND instrument_id=NEW.instrument_id ORDER BY revision DESC LIMIT 1),0)
 THEN RAISE(ABORT,'daily mainline clock moved backwards') END;
END;

CREATE TRIGGER completed_backtest_gate BEFORE UPDATE OF status ON backtest_run WHEN NEW.status='completed' BEGIN
 SELECT CASE WHEN OLD.status<>'running' THEN RAISE(ABORT,'backtest must run accepted range before completion') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot WHERE snapshot_id=NEW.result_snapshot_id AND module='backtest_result' AND state='published') THEN RAISE(ABORT,'completed backtest requires a published result') END;
END;

CREATE TRIGGER completed_backtest_immutable BEFORE UPDATE ON backtest_run WHEN OLD.status='completed' BEGIN SELECT RAISE(ABORT,'completed backtest is immutable; rerun with new ID'); END;

CREATE TRIGGER completed_backtest_no_delete BEFORE DELETE ON backtest_run WHEN OLD.status='completed' AND workspace_purge_allowed('backtest',OLD.backtest_id)=0 BEGIN SELECT RAISE(ABORT,'retain completed backtest metadata'); END;

CREATE TRIGGER event_not_future_business_day BEFORE INSERT ON tracking_event
WHEN NEW.business_date>(SELECT business_date FROM business_clock WHERE singleton=1)
BEGIN SELECT RAISE(ABORT,'tracking event cannot run ahead of business clock'); END;

CREATE TRIGGER explicit_policy_migration BEFORE UPDATE OF current_policy_version ON tracking_round
WHEN NEW.current_policy_version<>OLD.current_policy_version AND NOT EXISTS(SELECT 1 FROM tracking_policy_application a WHERE a.round_id=OLD.round_id AND a.strategy_id=OLD.strategy_id AND a.previous_policy_version=OLD.current_policy_version AND a.policy_version=NEW.current_policy_version)
BEGIN SELECT RAISE(ABORT,'policy migration requires an audited application'); END;

CREATE TRIGGER freeze_published_snapshot BEFORE UPDATE ON dataset_snapshot
WHEN OLD.state='published' BEGIN SELECT RAISE(ABORT,'published snapshot is immutable; create a revision'); END;

CREATE TRIGGER freeze_selection_candidate_delete BEFORE DELETE ON selection_candidate WHEN (SELECT status FROM selection_run WHERE run_id=OLD.run_id)='completed' AND workspace_purge_allowed('selection',OLD.run_id)=0 BEGIN SELECT RAISE(ABORT,'completed run and candidates are immutable'); END;

CREATE TRIGGER freeze_selection_candidate_update BEFORE UPDATE ON selection_candidate WHEN (SELECT status FROM selection_run WHERE run_id=OLD.run_id)='completed' OR (SELECT status FROM selection_run WHERE run_id=NEW.run_id)='completed' BEGIN SELECT RAISE(ABORT,'completed run and candidates are immutable'); END;

CREATE TRIGGER freeze_selection_run_delete BEFORE DELETE ON selection_run WHEN OLD.status='completed' AND workspace_purge_allowed('selection',OLD.run_id)=0 BEGIN SELECT RAISE(ABORT,'completed run and candidates are immutable'); END;

CREATE TRIGGER freeze_selection_run_update BEFORE UPDATE ON selection_run WHEN OLD.status='completed' BEGIN SELECT RAISE(ABORT,'completed run and candidates are immutable'); END;

CREATE TRIGGER freeze_snapshot_artifact_delete BEFORE DELETE ON snapshot_artifact WHEN (SELECT state FROM dataset_snapshot WHERE snapshot_id=OLD.snapshot_id)='published' BEGIN SELECT RAISE(ABORT,'published content and coverage are immutable'); END;

CREATE TRIGGER freeze_snapshot_artifact_insert BEFORE INSERT ON snapshot_artifact WHEN (SELECT state FROM dataset_snapshot WHERE snapshot_id=NEW.snapshot_id)='published' BEGIN SELECT RAISE(ABORT,'published content and coverage are immutable'); END;

CREATE TRIGGER freeze_snapshot_artifact_update BEFORE UPDATE ON snapshot_artifact WHEN (SELECT state FROM dataset_snapshot WHERE snapshot_id=OLD.snapshot_id)='published' OR (SELECT state FROM dataset_snapshot WHERE snapshot_id=NEW.snapshot_id)='published' BEGIN SELECT RAISE(ABORT,'published content and coverage are immutable'); END;

CREATE TRIGGER freeze_snapshot_coverage_delete BEFORE DELETE ON snapshot_coverage WHEN (SELECT state FROM dataset_snapshot WHERE snapshot_id=OLD.snapshot_id)='published' BEGIN SELECT RAISE(ABORT,'published content and coverage are immutable'); END;

CREATE TRIGGER freeze_snapshot_coverage_insert BEFORE INSERT ON snapshot_coverage WHEN (SELECT state FROM dataset_snapshot WHERE snapshot_id=NEW.snapshot_id)='published' BEGIN SELECT RAISE(ABORT,'published content and coverage are immutable'); END;

CREATE TRIGGER freeze_snapshot_coverage_update BEFORE UPDATE ON snapshot_coverage WHEN (SELECT state FROM dataset_snapshot WHERE snapshot_id=OLD.snapshot_id)='published' OR (SELECT state FROM dataset_snapshot WHERE snapshot_id=NEW.snapshot_id)='published' BEGIN SELECT RAISE(ABORT,'published content and coverage are immutable'); END;

CREATE TRIGGER frozen_range_acceptance BEFORE UPDATE OF range_acceptance_json ON backtest_run WHEN OLD.status<>'queued' AND NEW.range_acceptance_json<>OLD.range_acceptance_json BEGIN SELECT RAISE(ABORT,'accepted range is frozen once running'); END;

CREATE TRIGGER gc_identity_immutable BEFORE UPDATE ON snapshot_gc WHEN NEW.snapshot_id<>OLD.snapshot_id BEGIN SELECT RAISE(ABORT,'GC marker identity is immutable'); END;

CREATE TRIGGER gc_insert_guard BEFORE INSERT ON snapshot_gc WHEN NEW.state<>'available' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM published_head WHERE snapshot_id=NEW.snapshot_id) OR EXISTS(SELECT 1 FROM retention_pin WHERE snapshot_id=NEW.snapshot_id AND (expires_at_ms IS NULL OR expires_at_ms>unixepoch()*1000))
 THEN RAISE(ABORT,'head or live pin prevents garbage collection') END;
END;

CREATE TRIGGER gc_marker_retained BEFORE DELETE ON snapshot_gc BEGIN SELECT RAISE(ABORT,'retain artifact availability history'); END;

CREATE TRIGGER gc_no_resurrection BEFORE UPDATE ON snapshot_gc WHEN OLD.state='purged' OR (OLD.state='gc_pending' AND NEW.state='available') BEGIN SELECT RAISE(ABORT,'unavailable artifacts require a new verified snapshot, not marker reset'); END;

CREATE TRIGGER gc_update_guard BEFORE UPDATE ON snapshot_gc WHEN NEW.state<>'available' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM published_head WHERE snapshot_id=NEW.snapshot_id) OR EXISTS(SELECT 1 FROM retention_pin WHERE snapshot_id=NEW.snapshot_id AND (expires_at_ms IS NULL OR expires_at_ms>unixepoch()*1000))
 THEN RAISE(ABORT,'head or live pin prevents garbage collection') END;
END;

CREATE TRIGGER head_insert_gate BEFORE INSERT ON published_head BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot s WHERE s.snapshot_id=NEW.snapshot_id AND s.state='published' AND s.module=NEW.module AND s.scope_key=NEW.scope_key)
 THEN RAISE(ABORT,'head must reference matching published module and scope') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM snapshot_gc WHERE snapshot_id=NEW.snapshot_id AND state<>'available') THEN RAISE(ABORT,'head snapshot artifacts unavailable') END;
END;

CREATE TRIGGER head_update_gate BEFORE UPDATE ON published_head BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot s WHERE s.snapshot_id=NEW.snapshot_id AND s.state='published' AND s.module=NEW.module AND s.scope_key=NEW.scope_key)
 THEN RAISE(ABORT,'head must reference matching published module and scope') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM snapshot_gc WHERE snapshot_id=NEW.snapshot_id AND state<>'available') THEN RAISE(ABORT,'head snapshot artifacts unavailable') END;
END;

CREATE TRIGGER insert_snapshot_staged_only BEFORE INSERT ON dataset_snapshot
WHEN NEW.state='published' BEGIN SELECT RAISE(ABORT,'insert staged then validate and publish'); END;

CREATE TRIGGER job_event_order BEFORE INSERT ON job_event
WHEN NEW.seq<>coalesce((SELECT max(seq)+1 FROM job_event WHERE job_id=NEW.job_id),1)
BEGIN SELECT RAISE(ABORT,'job events require contiguous per-job seq'); END;

CREATE TRIGGER line_alert_rule_delete AFTER DELETE ON chart_annotation
WHEN OLD.line_type!='reference' AND json_array_length(OLD.alert_modes_json)>0
BEGIN INSERT INTO line_alert_rule_clock VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER line_alert_rule_insert AFTER INSERT ON chart_annotation
WHEN NEW.line_type!='reference' AND json_array_length(NEW.alert_modes_json)>0
BEGIN INSERT INTO line_alert_rule_clock VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER line_alert_rule_update AFTER UPDATE OF price,price_basis,anchor_date,line_type,alert_modes_json,auto_watchlist,revision,effective_business_date ON chart_annotation
WHEN (OLD.line_type!='reference' AND json_array_length(OLD.alert_modes_json)>0 OR NEW.line_type!='reference' AND json_array_length(NEW.alert_modes_json)>0)
AND (OLD.price IS NOT NEW.price OR OLD.price_basis IS NOT NEW.price_basis OR OLD.anchor_date IS NOT NEW.anchor_date
 OR OLD.line_type IS NOT NEW.line_type OR OLD.alert_modes_json IS NOT NEW.alert_modes_json
 OR OLD.auto_watchlist IS NOT NEW.auto_watchlist OR OLD.revision IS NOT NEW.revision OR OLD.effective_business_date IS NOT NEW.effective_business_date)
BEGIN INSERT INTO line_alert_rule_clock VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER no_snapshot_id_replace BEFORE INSERT ON dataset_snapshot WHEN EXISTS(SELECT 1 FROM dataset_snapshot WHERE snapshot_id=NEW.snapshot_id) BEGIN SELECT RAISE(ABORT,'snapshot ID already exists; no replace'); END;

CREATE TRIGGER no_tracking_reactivation BEFORE UPDATE OF status ON tracking_round WHEN OLD.status<>'tracking' AND NEW.status<>OLD.status
BEGIN SELECT RAISE(ABORT,'ended round stays historical; create a new round'); END;

CREATE TRIGGER pin_identity_immutable BEFORE UPDATE ON retention_pin WHEN NEW.snapshot_id<>OLD.snapshot_id OR NEW.owner_kind<>OLD.owner_kind OR NEW.owner_id<>OLD.owner_id BEGIN SELECT RAISE(ABORT,'pin identity is immutable'); END;

CREATE TRIGGER pin_live_artifacts BEFORE INSERT ON retention_pin BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot WHERE snapshot_id=NEW.snapshot_id AND state='published') OR EXISTS(SELECT 1 FROM snapshot_gc WHERE snapshot_id=NEW.snapshot_id AND state<>'available')
 THEN RAISE(ABORT,'cannot pin unpublished or unavailable snapshot') END;
END;

CREATE TRIGGER pin_renew_live BEFORE UPDATE OF expires_at_ms ON retention_pin BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM snapshot_gc WHERE snapshot_id=NEW.snapshot_id AND state<>'available') THEN RAISE(ABORT,'cannot renew unavailable artifacts') END;
END;

CREATE TRIGGER policy_application_matches_round BEFORE INSERT ON tracking_policy_application BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tracking_round WHERE round_id=NEW.round_id AND strategy_id=NEW.strategy_id AND current_policy_version=NEW.previous_policy_version AND status='tracking') THEN RAISE(ABORT,'policy application must match active round and current policy') END;
 SELECT CASE WHEN NEW.effective_business_date IS NOT (SELECT business_date FROM business_clock WHERE singleton=1) THEN RAISE(ABORT,'policy migration takes effect on current business day') END;
END;

CREATE TRIGGER publish_snapshot_gate BEFORE UPDATE OF state ON dataset_snapshot
WHEN NEW.state='published' AND OLD.state<>'published'
BEGIN
  SELECT CASE WHEN OLD.state<>'validated' THEN RAISE(ABORT,'snapshot must be validated before publication') END;
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM snapshot_artifact WHERE snapshot_id=NEW.snapshot_id) THEN RAISE(ABORT,'published snapshot requires artifacts') END;
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM snapshot_coverage WHERE snapshot_id=NEW.snapshot_id) THEN RAISE(ABORT,'published snapshot requires coverage') END;
END;

CREATE TRIGGER retain_line_alert_delete BEFORE DELETE ON line_alert_event BEGIN SELECT RAISE(ABORT,'retain line alert evidence'); END;

CREATE TRIGGER retain_line_alert_update BEFORE UPDATE ON line_alert_event BEGIN SELECT RAISE(ABORT,'retain line alert evidence'); END;

CREATE TRIGGER retain_listing_confirmation_delete BEFORE DELETE ON listing_status_confirmation BEGIN SELECT RAISE(ABORT,'retain listing confirmation audit'); END;

CREATE TRIGGER retain_listing_confirmation_update BEFORE UPDATE ON listing_status_confirmation BEGIN SELECT RAISE(ABORT,'retain listing confirmation audit'); END;

CREATE TRIGGER retain_mainline_revision_delete BEFORE DELETE ON market_mainline_revision
BEGIN SELECT RAISE(ABORT,'retain daily mainline audit'); END;

CREATE TRIGGER retain_mainline_revision_update BEFORE UPDATE ON market_mainline_revision
BEGIN SELECT RAISE(ABORT,'retain daily mainline audit'); END;

CREATE TRIGGER retain_published_snapshot_metadata BEFORE DELETE ON dataset_snapshot
WHEN OLD.state='published' BEGIN SELECT RAISE(ABORT,'retain publication metadata; GC artifacts separately'); END;

CREATE TRIGGER retain_sentiment_snapshot_delete BEFORE DELETE ON market_sentiment_snapshot
BEGIN SELECT RAISE(ABORT,'retain manual sentiment snapshot'); END;

CREATE TRIGGER retain_sentiment_snapshot_replace BEFORE INSERT ON market_sentiment_snapshot
WHEN EXISTS(SELECT 1 FROM market_sentiment_snapshot WHERE snapshot_id=NEW.snapshot_id
 OR (trade_date=NEW.trade_date AND rule_version=NEW.rule_version AND input_fingerprint=NEW.input_fingerprint))
BEGIN SELECT RAISE(ABORT,'retain manual sentiment snapshot'); END;

CREATE TRIGGER retain_sentiment_snapshot_update BEFORE UPDATE ON market_sentiment_snapshot
BEGIN SELECT RAISE(ABORT,'retain manual sentiment snapshot'); END;

CREATE TRIGGER sector_tracking_entry_gate BEFORE INSERT ON sector_tracking_round BEGIN
 SELECT CASE WHEN NOT EXISTS(
  SELECT 1 FROM sector_selection_run r JOIN sector_selection_candidate c ON c.run_id=r.run_id
   JOIN sector_strategy s ON s.strategy_id=r.strategy_id
   JOIN sector_strategy_version v ON v.strategy_id=r.strategy_id AND v.version=r.strategy_version
  WHERE r.run_id=NEW.origin_run_id AND r.status='completed' AND r.strategy_id=NEW.strategy_id
   AND r.strategy_version=NEW.entry_strategy_version AND r.business_date=NEW.entry_business_date
   AND r.business_date=(SELECT business_date FROM business_clock WHERE singleton=1)
   AND r.market_snapshot_id=NEW.entry_market_snapshot_id AND s.current_version=r.strategy_version
   AND s.archived=0 AND c.topic_code=NEW.topic_code AND c.decision='matched'
   AND c.close_price_e8=NEW.entry_price_e8 AND c.name=NEW.name AND c.sector_kind=NEW.sector_kind
   AND c.cache_refs_json=NEW.entry_cache_refs_json AND v.period=NEW.entry_period
 ) THEN RAISE(ABORT,'sector entry requires a current matched run and frozen daily close') END;
END;

CREATE TRIGGER sector_tracking_entry_immutable BEFORE UPDATE ON sector_tracking_round
 WHEN NEW.strategy_id<>OLD.strategy_id OR NEW.entry_strategy_version<>OLD.entry_strategy_version
  OR NEW.origin_run_id<>OLD.origin_run_id OR NEW.target_id<>OLD.target_id OR NEW.topic_code<>OLD.topic_code
  OR NEW.topic_id<>OLD.topic_id OR NEW.name<>OLD.name OR NEW.sector_kind<>OLD.sector_kind
  OR NEW.entry_period<>OLD.entry_period OR NEW.entry_business_date<>OLD.entry_business_date
  OR NEW.entry_price_e8<>OLD.entry_price_e8 OR NEW.entry_high_e8 IS NOT OLD.entry_high_e8
  OR NEW.entry_low_e8 IS NOT OLD.entry_low_e8 OR NEW.entry_market_snapshot_id<>OLD.entry_market_snapshot_id
  OR NEW.entry_cache_refs_json<>OLD.entry_cache_refs_json OR NEW.entry_basis_json<>OLD.entry_basis_json
  OR NEW.entry_policy_json<>OLD.entry_policy_json
 BEGIN SELECT RAISE(ABORT,'sector tracking entry is immutable'); END;

CREATE TRIGGER sector_tracking_event_date_gate BEFORE INSERT ON sector_tracking_event
 WHEN NEW.business_date<(SELECT entry_business_date FROM sector_tracking_round WHERE round_id=NEW.round_id)
 BEGIN SELECT RAISE(ABORT,'sector tracking event predates entry'); END;

CREATE TRIGGER sector_tracking_event_immutable_delete BEFORE DELETE ON sector_tracking_event
 BEGIN SELECT RAISE(ABORT,'sector tracking events are immutable'); END;

CREATE TRIGGER sector_tracking_event_immutable_update BEFORE UPDATE ON sector_tracking_event
 BEGIN SELECT RAISE(ABORT,'sector tracking events are immutable'); END;

CREATE TRIGGER sector_tracking_no_reactivation BEFORE UPDATE OF status ON sector_tracking_round
 WHEN OLD.status<>'tracking' AND NEW.status<>OLD.status
 BEGIN SELECT RAISE(ABORT,'ended sector rounds cannot be reactivated'); END;

CREATE TRIGGER selection_dependency_gate BEFORE INSERT ON selection_run BEGIN
 SELECT CASE WHEN json_type(NEW.input_snapshots_json)<>'object' OR EXISTS(
  SELECT 1 FROM json_each(NEW.input_snapshots_json) j WHERE j.type<>'text' OR NOT EXISTS(SELECT 1 FROM dataset_snapshot s WHERE s.snapshot_id=j.value AND s.state='published')
  OR EXISTS(SELECT 1 FROM snapshot_gc g WHERE g.snapshot_id=j.value AND g.state<>'available')) THEN RAISE(ABORT,'selection dependencies must be available published snapshots') END;
END;

CREATE TRIGGER selection_input_gate BEFORE INSERT ON selection_run BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dataset_snapshot WHERE snapshot_id=NEW.primary_snapshot_id AND state='published' AND data_end>=NEW.business_date) THEN RAISE(ABORT,'selection requires published input covering business date') END;
 SELECT CASE WHEN NEW.status<>'running' THEN RAISE(ABORT,'selection starts running; seal after candidates are saved') END;
END;

CREATE TRIGGER selection_input_immutable BEFORE UPDATE ON selection_run
WHEN NEW.strategy_id<>OLD.strategy_id OR NEW.strategy_version<>OLD.strategy_version OR NEW.business_date<>OLD.business_date OR NEW.primary_snapshot_id<>OLD.primary_snapshot_id OR NEW.input_snapshots_json<>OLD.input_snapshots_json OR NEW.input_sha256<>OLD.input_sha256 OR NEW.universe_definition_json<>OLD.universe_definition_json
BEGIN SELECT RAISE(ABORT,'selection input is frozen at creation'); END;

CREATE TRIGGER sentiment_snapshot_clock BEFORE INSERT ON market_sentiment_snapshot
WHEN NEW.recorded_at_ms<coalesce((SELECT max(recorded_at_ms) FROM market_sentiment_snapshot),0)
BEGIN SELECT RAISE(ABORT,'sentiment snapshot clock moved backwards'); END;

CREATE TRIGGER snapshot_ready_coverage BEFORE UPDATE OF state ON dataset_snapshot WHEN NEW.state='published' AND NEW.quality='ready' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM snapshot_coverage WHERE snapshot_id=NEW.snapshot_id AND coverage_state<>'ready') THEN RAISE(ABORT,'ready snapshot cannot hide partial coverage') END;
END;

CREATE TRIGGER topic_override_current_day BEFORE INSERT ON topic_override
WHEN NEW.effective_business_date IS NOT (SELECT business_date FROM business_clock WHERE singleton=1)
BEGIN SELECT RAISE(ABORT,'manual override cannot backfill historical membership'); END;

CREATE TRIGGER topic_revision_current_day BEFORE INSERT ON topic_revision
WHEN NEW.effective_business_date IS NOT (SELECT business_date FROM business_clock WHERE singleton=1)
BEGIN SELECT RAISE(ABORT,'manual topic revision must take effect on current business day'); END;

CREATE TRIGGER tracking_entry_gate BEFORE INSERT ON tracking_round BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM selection_run r JOIN selection_candidate c ON c.run_id=r.run_id JOIN strategy s ON s.strategy_id=r.strategy_id
  WHERE r.run_id=NEW.origin_run_id AND c.instrument_id=NEW.instrument_id AND c.decision='matched' AND c.close_price_e8=NEW.entry_price_e8
  AND r.status='completed' AND r.strategy_id=NEW.strategy_id AND r.strategy_version=NEW.entry_strategy_version AND r.business_date=NEW.entry_business_date
  AND r.primary_snapshot_id=NEW.entry_snapshot_id AND s.current_version=r.strategy_version AND s.current_policy_version=NEW.entry_policy_version
  AND NEW.current_policy_version=NEW.entry_policy_version AND NEW.entry_business_date=(SELECT business_date FROM business_clock WHERE singleton=1))
 THEN RAISE(ABORT,'tracking requires a matched completed run and frozen entry basis') END;
 SELECT CASE WHEN json_type(NEW.entry_basis_json,'$.comparison_basis_id') IS NOT 'text' THEN RAISE(ABORT,'tracking entry requires a frozen comparison basis') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tracking_ignore WHERE strategy_id=NEW.strategy_id AND instrument_id=NEW.instrument_id AND active=1) THEN RAISE(ABORT,'release ignore before tracking again') END;
END;

CREATE TRIGGER tracking_entry_immutable BEFORE UPDATE ON tracking_round
WHEN NEW.strategy_id<>OLD.strategy_id OR NEW.instrument_id<>OLD.instrument_id OR NEW.origin_run_id<>OLD.origin_run_id OR NEW.entry_strategy_version<>OLD.entry_strategy_version
 OR NEW.entry_business_date<>OLD.entry_business_date OR NEW.entry_price_e8<>OLD.entry_price_e8 OR NEW.entry_snapshot_id<>OLD.entry_snapshot_id OR NEW.entry_policy_version<>OLD.entry_policy_version OR NEW.entry_basis_json<>OLD.entry_basis_json
BEGIN SELECT RAISE(ABORT,'entry day price and strategy basis cannot be reset'); END;

CREATE TRIGGER tracking_event_date_guard BEFORE INSERT ON tracking_event BEGIN
 SELECT CASE WHEN NEW.event_type IN ('alert','condition_end','expire') AND (json_type(NEW.evidence_json,'$.policy_version') IS NOT 'integer' OR NOT EXISTS(SELECT 1 FROM tracking_round r JOIN tracking_policy_version p ON p.strategy_id=r.strategy_id AND p.policy_version=json_extract(NEW.evidence_json,'$.policy_version') WHERE r.round_id=NEW.round_id)) THEN RAISE(ABORT,'trigger event requires explicit valid historical policy evidence') END;
 SELECT CASE WHEN NEW.business_date<(SELECT entry_business_date FROM tracking_round WHERE round_id=NEW.round_id) THEN RAISE(ABORT,'event predates tracking round') END;
 SELECT CASE WHEN NEW.trading_age=0 AND NEW.event_type='expire' THEN RAISE(ABORT,'day zero cannot expire') END;
 SELECT CASE WHEN NEW.event_type IN ('alert','condition_end') AND (NEW.trading_age=0 OR NEW.business_date=(SELECT entry_business_date FROM tracking_round WHERE round_id=NEW.round_id)) AND NOT EXISTS(
  SELECT 1 FROM tracking_round r JOIN tracking_policy_version p ON p.strategy_id=r.strategy_id AND p.policy_version=json_extract(NEW.evidence_json,'$.policy_version') WHERE r.round_id=NEW.round_id
  AND ((NEW.event_type='alert' AND p.allow_entry_day_alerts=1) OR (NEW.event_type='condition_end' AND p.allow_entry_day_exits=1))) THEN RAISE(ABORT,'day-zero signal needs explicit policy opt-in') END;
 SELECT CASE WHEN NEW.event_type IN ('alert','condition_end') AND (NEW.data_state<>'ready' OR NEW.outcome<>'satisfied') THEN RAISE(ABORT,'unknown data cannot trigger an alert or condition exit') END;
END;

CREATE TRIGGER tracking_exit_evidence BEFORE INSERT ON tracking_event WHEN NEW.event_type='condition_end' AND json_extract(NEW.evidence_json,'$.condition_key')='close_below_entry' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tracking_round r WHERE r.round_id=NEW.round_id
  AND json_type(NEW.evidence_json,'$.normalized_observed_close_e8')='integer'
  AND json_extract(NEW.evidence_json,'$.normalized_observed_close_e8')>0
  AND json_extract(NEW.evidence_json,'$.normalized_observed_close_e8')<r.entry_price_e8
  AND json_extract(NEW.evidence_json,'$.reference_entry_e8')=r.entry_price_e8
  AND json_extract(NEW.evidence_json,'$.reference_entry_date')=r.entry_business_date
  AND json_extract(NEW.evidence_json,'$.comparison_basis_id')=json_extract(r.entry_basis_json,'$.comparison_basis_id')
  AND json_type(NEW.evidence_json,'$.provider_observed_close_e8')='integer'
  AND json_extract(NEW.evidence_json,'$.provider_observed_close_e8')>0
  AND json_extract(NEW.evidence_json,'$.normalization_state') IN ('verified','not_required')
  AND EXISTS(SELECT 1 FROM dataset_snapshot a WHERE a.snapshot_id=json_extract(NEW.evidence_json,'$.adjustment_snapshot_id') AND a.state='published' AND a.module IN ('analysis_bars','corporate_actions')))
 THEN RAISE(ABORT,'entry-price exit requires strict break of this round frozen baseline') END;
END;

CREATE TRIGGER tracking_round_no_delete BEFORE DELETE ON tracking_round WHEN workspace_purge_allowed('round',OLD.round_id)=0 BEGIN SELECT RAISE(ABORT,'soft-end tracking round; retain history'); END;

CREATE TRIGGER tracking_status_requires_event BEFORE UPDATE OF status ON tracking_round WHEN NEW.status<>OLD.status BEGIN
 SELECT CASE WHEN NEW.end_reason IS NULL OR length(NEW.end_reason)=0 OR NOT EXISTS(SELECT 1 FROM tracking_event e WHERE e.round_id=OLD.round_id AND e.business_date=NEW.end_business_date
  AND ((NEW.status='condition_ended' AND e.event_type='condition_end') OR (NEW.status='expired' AND e.event_type='expire') OR (NEW.status='manual_removed' AND e.event_type='manual_remove')))
 THEN RAISE(ABORT,'end round and its evidence event in one transaction') END;
END;

CREATE TRIGGER tracking_terminal_event_gate BEFORE INSERT ON tracking_event WHEN NEW.event_type IN ('alert','condition_end','expire') BEGIN
 SELECT CASE WHEN (SELECT status FROM tracking_round WHERE round_id=NEW.round_id)<>'tracking' THEN RAISE(ABORT,'ended round does not emit new live triggers') END;
 SELECT CASE WHEN NEW.event_type='expire' AND NOT EXISTS(SELECT 1 FROM tracking_round r JOIN tracking_policy_version p ON p.strategy_id=r.strategy_id AND p.policy_version=json_extract(NEW.evidence_json,'$.policy_version') WHERE r.round_id=NEW.round_id AND NEW.trading_age>=p.duration_sessions) THEN RAISE(ABORT,'expiry requires policy trading-session age') END;
END;

CREATE TRIGGER watchlist_entry_baseline_frozen BEFORE UPDATE ON watchlist_item
WHEN OLD.watchlist_entry_price_e8 IS NOT NULL AND (
  NEW.watchlist_entry_price_e8 IS NOT OLD.watchlist_entry_price_e8
  OR NEW.watchlist_entry_basis_json IS NOT OLD.watchlist_entry_basis_json
  OR NEW.added_business_date IS NOT OLD.added_business_date
  OR NEW.instrument_id IS NOT OLD.instrument_id
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
) BEGIN
  SELECT RAISE(ABORT,'watchlist first-added closing baseline is immutable');
END;

CREATE TRIGGER workspace_purge_audit_delete BEFORE DELETE ON workspace_purge_audit BEGIN SELECT RAISE(ABORT,'retain permanent deletion audit'); END;

CREATE TRIGGER workspace_purge_audit_update BEFORE UPDATE ON workspace_purge_audit BEGIN SELECT RAISE(ABORT,'retain permanent deletion audit'); END;

CREATE TRIGGER workspace_purge_file_identity BEFORE UPDATE ON workspace_purge_file
WHEN NEW.purge_id<>OLD.purge_id OR NEW.snapshot_id<>OLD.snapshot_id OR NEW.object_key<>OLD.object_key OR NEW.sha256<>OLD.sha256 OR NEW.byte_count<>OLD.byte_count OR NEW.removed_bytes<OLD.removed_bytes
BEGIN SELECT RAISE(ABORT,'purge file authorization is immutable'); END;

CREATE TRIGGER workspace_purge_file_retained BEFORE DELETE ON workspace_purge_file BEGIN SELECT RAISE(ABORT,'retain permanent deletion file audit'); END;

CREATE TRIGGER workspace_purge_identity BEFORE UPDATE ON workspace_purge
WHEN NEW.purge_id<>OLD.purge_id OR NEW.target_kind<>OLD.target_kind OR NEW.target_id<>OLD.target_id OR NEW.target_name<>OLD.target_name OR NEW.job_id<>OLD.job_id OR NEW.scope_sha256<>OLD.scope_sha256 OR NEW.scope_json<>OLD.scope_json OR NEW.created_at_ms<>OLD.created_at_ms OR NEW.business_deleted<OLD.business_deleted OR (OLD.superseded_by IS NOT NULL AND NEW.superseded_by IS NOT OLD.superseded_by)
BEGIN SELECT RAISE(ABORT,'purge authorization is immutable'); END;

CREATE TRIGGER workspace_purge_retained BEFORE DELETE ON workspace_purge BEGIN SELECT RAISE(ABORT,'retain permanent deletion audit'); END;

COMMIT;
